<script setup lang="ts">
import {computed,nextTick,onBeforeUnmount,onMounted,ref,watch} from 'vue';
import {CheckCircle2,FileArchive,LoaderCircle,Upload,X} from 'lucide-vue-next';
import type {ZipImportInspection,ZipImportMapping,ZipImportPlan} from '../../../../packages/shared/src/releases';
import {post,request} from '../api';
import {useAppStore} from '../stores/app';
import WorkflowSteps from './WorkflowSteps.vue';
const props=defineProps<{base:string;branch:string;expectedCommit:string}>(),emit=defineEmits<{close:[];imported:[result:{commitId:string;totalRows:number}]} >(),app=useAppStore();
const dialog=ref<HTMLElement>(),file=ref<File>(),inspection=ref<ZipImportInspection>(),mode=ref<ZipImportMapping['mode']>('tables'),paths=ref<string[]>([]),idField=ref(''),attachmentFields=ref<string[]>([]),busy=ref(false),committing=ref(false),error=ref(''),confirmed=ref(false),message=ref('导入样本'),plan=ref<ZipImportPlan>(),preview=ref<{configured:boolean;rowCount:number;totalRows:number;previewFingerprint:string;warnings:string[]}>();
let generation=0,opener:HTMLElement|undefined;
const modes=computed(()=>[...new Set(inspection.value?.candidates.map(candidate=>candidate.mode)??[])]),options=computed(()=>[...new Set(inspection.value?.candidates.filter(candidate=>candidate.mode===mode.value).flatMap(candidate=>candidate.paths)??[])]),columns=computed(()=>[...new Set(inspection.value?.candidates.filter(candidate=>candidate.mode===mode.value).flatMap(candidate=>candidate.columns??[])??[])]);
const names:Record<ZipImportMapping['mode'],string>={tables:'表格记录',directories:'Skill目录（每目录压缩为ZIP）',archives:'每个ZIP附件一个样本',release:'标准发布数据包'};
const mapping=():ZipImportMapping=>({mode:mode.value,paths:paths.value,...(mode.value==='tables'&&idField.value?{idField:idField.value}:{}),...(mode.value==='tables'&&attachmentFields.value.length?{attachmentFields:attachmentFields.value}:{})});
function chooseMode(){paths.value=options.value.slice();idField.value='';attachmentFields.value=[];}
async function choose(value?:File){if(!value||busy.value||committing.value)return;if(value.size>64*1024*1024){plan.value=undefined;preview.value=undefined;confirmed.value=false;error.value='新选择的文件超过64MiB，未加载或提交；请重新选择文件。';return;}const current=++generation,previous=inspection.value?.id;busy.value=true;error.value='';plan.value=undefined;preview.value=undefined;confirmed.value=false;inspection.value=undefined;file.value=value;try{if(previous)await request('/import/zip/'+previous,{method:'DELETE'}).catch(()=>{});const form=new FormData();form.append('file',value);const result=await request<ZipImportInspection>(props.base+'/dataset/import/inspect',{method:'POST',body:form});if(current!==generation)return;file.value=value;inspection.value=result;mode.value=result.candidates[0]?.mode??'tables';chooseMode();}catch(cause){if(current===generation)error.value=(cause as Error).message;}finally{if(current===generation)busy.value=false;}}
async function validate(){if(!inspection.value||!paths.value.length)return;busy.value=true;error.value='';const current=++generation;try{const selected=mapping(),generic=await post<ZipImportPlan>('/import/zip/'+inspection.value.id+'/plan',selected);const target=await post<NonNullable<typeof preview.value>>(props.base+'/dataset/import/'+inspection.value.id+'/preview',{ref:props.branch,expectedCommit:props.expectedCommit,mapping:selected,fingerprint:generic.fingerprint});if(current!==generation)return;plan.value=generic;preview.value=target;confirmed.value=false;}catch(cause){if(current===generation)error.value=(cause as Error).message;}finally{if(current===generation)busy.value=false;}}
async function commit(){if(!inspection.value||!plan.value||!preview.value||!confirmed.value||!message.value.trim())return;committing.value=true;error.value='';const current=++generation;try{const result=await post<{commitId:string;totalRows:number}>(props.base+'/dataset/import/'+inspection.value.id+'/commit',{ref:props.branch,expectedCommit:props.expectedCommit,mapping:mapping(),fingerprint:plan.value.fingerprint,previewFingerprint:preview.value.previewFingerprint,message:message.value.trim()});if(current===generation)emit('imported',result);}catch(cause){error.value=(cause as Error).message;}finally{committing.value=false;}}
async function close(){if(busy.value||committing.value)return;if(file.value&&!await app.confirmAction('关闭会清理本次临时检查文件，下次需要重新选择；当前数据集没有提交或改变。',{title:'关闭导入',confirmLabel:'关闭预览'}))return;emit('close');}
function keydown(event:KeyboardEvent){if(event.key==='Escape'){event.preventDefault();event.stopPropagation();void close();}if(event.key!=='Tab')return;const items=[...dialog.value?.querySelectorAll<HTMLElement>('button:not(:disabled),input:not(:disabled),select:not(:disabled)')??[]],first=items[0],last=items.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}}
watch([mode,paths,idField,attachmentFields,()=>props.expectedCommit,()=>props.branch],()=>{plan.value=undefined;preview.value=undefined;confirmed.value=false;},{deep:true});
onMounted(async()=>{opener=document.activeElement as HTMLElement;await nextTick();dialog.value?.querySelector<HTMLElement>('input')?.focus();});onBeforeUnmount(()=>{generation++;if(inspection.value)void request('/import/zip/'+inspection.value.id,{method:'DELETE'}).catch(()=>{});opener?.focus();});
</script>
<template><div class="modal-backdrop dataset-import-backdrop" @click.self="close" @keydown="keydown"><section ref="dialog" class="modal dataset-import-panel" role="dialog" aria-modal="true" aria-labelledby="dataset-import-title"><header><div><h2 id="dataset-import-title"><Upload :size="19"/>导入样本</h2><p>{{branch}} · 基点 {{expectedCommit.slice(0,12)}}。预览后明确提交；原数据及人工标注不会被覆盖。</p></div><button class="icon-button" aria-label="关闭样本导入" :disabled="busy||committing" @click="close"><X :size="19"/></button></header><main><WorkflowSteps :steps="['选择文件','核对映射','预览与校验','明确提交']" :current="committing?3:preview?2:inspection?1:0" label="样本导入步骤"/><label class="dataset-import-drop"><FileArchive :size="26"/><strong>{{file?.name??'选择 CSV、JSONL 或 ZIP 数据包'}}</strong><span>UTF-8 CSV / TSV / JSONL / NDJSON，或受管ZIP；最大64MiB。Skill仅作为压缩数据，不安装、不执行。</span><input type="file" accept=".csv,.tsv,.jsonl,.ndjson,.zip" :disabled="busy||committing" aria-label="选择样本导入文件" @change="choose(($event.target as HTMLInputElement).files?.[0])"/></label><p v-if="busy" class="dataset-import-working" role="status"><LoaderCircle class="spin" :size="15"/>正在检查文件、映射及目标版本…</p><template v-if="inspection"><p v-for="warning in inspection.warnings" :key="warning" class="dataset-import-note">{{warning}}</p><label class="field">数据入口<select v-model="mode" :disabled="busy||committing" @change="chooseMode"><option v-for="item in modes" :key="item" :value="item">{{names[item]}}</option></select></label><div class="dataset-import-paths"><label v-for="path in options" :key="path"><input v-model="paths" type="checkbox" :value="path" :disabled="busy||committing"/>{{path||'根目录Skill'}}</label></div><template v-if="mode==='tables'"><label class="field">稳定身份字段（可选）<select v-model="idField" :disabled="busy||committing"><option value="">按原文件和记录位置生成独立身份</option><option v-for="column in columns" :key="column" :value="column">{{column}}</option></select></label><fieldset><legend>附件路径字段（可选）</legend><label v-for="column in columns" :key="column" class="dataset-import-option"><input v-model="attachmentFields" type="checkbox" :value="column" :disabled="busy||committing"/>{{column}}</label></fieldset><p class="dataset-import-note">CSV/TSV保留文本值；JSONL保留原始JSON类型。类型、业务标识和附件不匹配会阻止导入，不会静默转换。</p></template><button class="btn" :disabled="!paths.length||busy||committing" @click="validate"><CheckCircle2 :size="14"/>预览并校验目标数据集</button></template><section v-if="plan&&preview" class="dataset-import-summary"><h3>{{preview.configured?'追加导入':'建立数据集并导入'}} · {{preview.rowCount.toLocaleString()}}条</h3><p>提交后共 {{preview.totalRows.toLocaleString()}} 条样本 · {{plan.columns.length}} 个源字段 · {{plan.attachmentCount}} 个压缩附件</p><p v-for="warning in [...plan.warnings,...preview.warnings]" :key="warning" class="dataset-import-note">{{warning}}</p><label class="field">提交说明<input v-model="message" :disabled="committing" maxlength="4000"/></label><label class="dataset-import-confirm"><input v-model="confirmed" type="checkbox" :disabled="committing"/>确认在此分支生成一次导入提交，原文件和映射作为来源保留。</label></section><p v-if="error" class="error-state" role="alert">{{error}}</p></main><footer><button class="btn" :disabled="busy||committing" @click="close">取消</button><button class="btn btn-primary" :disabled="!preview||!plan||!confirmed||!message.trim()||busy||committing" @click="commit"><LoaderCircle v-if="committing" class="spin" :size="15"/>{{committing?'正在导入并提交…':'确认导入并提交'}}</button></footer></section></div></template>
<style scoped>
.dataset-import-backdrop{z-index:120}.dataset-import-panel{width:min(780px,96vw);padding:0}.dataset-import-panel>header{display:flex;justify-content:space-between;align-items:flex-start;gap:15px;padding:21px;border-bottom:1px solid var(--line)}.dataset-import-panel h2{display:flex;gap:9px;align-items:center;font-size:18px}.dataset-import-panel header p,.dataset-import-summary>p{color:var(--muted);font-size:12px;line-height:1.8;margin-top:8px}.dataset-import-panel main{padding:20px;min-width:0}.dataset-import-drop{display:flex;align-items:center;flex-direction:column;text-align:center;gap:12px;padding:22px;border:1px dashed var(--line);border-radius:var(--radius);margin-bottom:18px;background:var(--bg)}.dataset-import-drop>span,.dataset-import-note{font-size:11px;color:var(--muted);line-height:1.8;overflow-wrap:anywhere}.dataset-import-drop input{max-width:100%;font-size:12px}.dataset-import-working{display:flex;gap:8px;align-items:center;font-size:12px;margin:15px 0}.dataset-import-note{margin:12px 0}.dataset-import-panel .field{font-size:12px;margin-top:16px}.dataset-import-paths{display:grid;gap:9px;max-height:220px;overflow:auto;padding:12px;border:1px solid var(--line);margin:12px 0}.dataset-import-paths label,.dataset-import-option,.dataset-import-confirm{font-size:12px;line-height:1.8;display:flex;gap:8px;align-items:center;overflow-wrap:anywhere}.dataset-import-panel fieldset{border:1px solid var(--line);padding:12px;display:flex;gap:12px;flex-wrap:wrap}.dataset-import-panel legend{font-size:11px;color:var(--muted);padding:0 5px}.dataset-import-summary{margin-top:20px;border:1px solid var(--line);padding:15px;border-radius:var(--radius)}.dataset-import-summary h3{font-size:14px}.dataset-import-panel>footer{display:flex;justify-content:flex-end;gap:10px;padding:17px 20px;border-top:1px solid var(--line)}
</style>
